      "童年的邓亚萍，因为受当时做体育教练的父亲的影响，立志做一名优秀的运动员。但是她个子矮，手脚粗短，根本不符合体校的要求，体校的大门没能向她敞开。于是，年幼的邓亚萍跟父亲学起了乒乓球，父亲规定她每天在练完体能课后，必须还要做100个发球接球的动作。邓亚萍虽然只有七八岁，但为了能使自己的球技更加熟练，基本功更加扎实，便在自己的腿上绑上了沙袋，而且把木牌换成了铁牌。对一个孩子来说，这是多么难能可贵！这不但要使身体备受煎熬，心理方面也要承受巨大的压力。小小的她，每闪、展、腾、挪一步，都可以用举步维艰来形容。腿肿了，手掌磨破了，这是家常便饭。但她从不叫苦、不喊累。负责训练的父亲，有时心疼得掉眼泪。付出总有回报，由于邓亚萍的执着，10岁的她便在全国少年乒乓球比赛中获得团体和单打两项冠军。",
