      "最使我难忘的,是我小学时候的女教师蔡芸芝先生。现在回想起来,她那时有十八九岁。右嘴角边有榆钱大小一块黑痣。在我的记忆里,她是一个温柔、美丽的人。",
      "她从来不打骂我们。仅仅有一次,她的教鞭好像要落下来,我用石板一迎,教鞭轻轻地敲在石板边上,大伙笑了,她也笑了。我用儿童的狡猾的眼光察觉,她爱我们,并没有存心要打的意思。每逢放假的时候,我们就更不愿离开她。我还记得,放假前我默默地站在她的身边,看她收拾这样那样东西的情景。蔡老师!我不知道你当时是不是察觉,一个孩子站在那里,对你是多么的依恋!至于暑假,对于一个喜欢他的老师的孩子来说,又是多么漫长!",
