    "id": "RD-381",
    "title": "心底盛开一朵花",
    "theme": "写事",
    "paragraphs": [
      "匆匆上了公交车我才发现没带公交卡。司机倒是不错,可能是看我不像是经常逃票的人,才没有把我撵(niǎn)下去,但让我在皮包里继续找零钱。在车上,我觉得自己像个小偷,把身上里里外外翻了个遍,除了几张百元整钞,再也没有找到一个硬币。那种尴尬和狼狈是我从来没有过的。面对车厢里几十人诧异的目光,我恨不能马上掏张百元大钞扔进投币箱来证明自己的粗心大意和清白。",
      "慌乱时,一个粗哑的声音从背后传来:“先生,我这里有一块钱,你拿去。”我回头一看,说话的是一位七十多岁的老太太,满脸黑色的皱纹,一套灰色的布衫,头上裹了条很旧的白毛巾,脚套一双褪了色的绣花鞋——一个典型的外地老太太。言语间,她已经替我把一块钱投了进去。我慌忙解释说:“那怎么可以,我怎么还您的钱呢?”老太太笑了:“一块钱,还什么?又不是一万元。”这时,我发现车里的人都冲我和老太太笑了,这种让我捉摸不透的笑容使我越发不安起来。他们越是这样,我越不好意思,迫不及待地说:“大娘,要不这样吧,我和您一道下车,您等我几分钟,我去买瓶水,换了零钱后给您。”",
      "老太太又笑了:“我下站就到了,下午回山东济宁老家。我儿子一家都在南京打工,我是专门来看孙子的。三年前,我第一次在南京坐车时,不知道要投币,身上也没有零钱,就像你现在的样子,是一位好心的姑娘帮我投了一块钱。今天我正好有机会还南京人一份情。下次,如果你在车上遇见像你一样的粗心人,替他投一块钱,就算你还我了,我把这一块钱暂时保存在你那里。”听了老太太的话,满车厢的人都笑了,笑得那么灿烂、那么自然。"
    ],
