    "id": "RD-382",
    "title": "“滑翔机之父”",
    "theme": "写人",
    "paragraphs": [
      "李林塔尔是德国工程师和滑翔飞行家,世界航空先驱者之一。他被世人称为“滑翔机之父”。",
      "青年时代的李林塔尔已经清楚地知道,将来的飞行器必然要依赖于机械动力。然而,当时他所面临的难题并不是有无动力,而是飞行器的结构设计和如何稳定操纵。",
      "李林塔尔选择了进行滑翔实验飞行的这条道路。为了设计出最理想的飞行器,他把主要精力放在对鸟类飞行原理的研究上。他耗费数年时间悉心观察,仔细研究各种鸟类的翅膀结构和飞翔的方法,尤其是注意到翼面和升力之间的关系。在7 年的时间里,他制造出18种不同型号的滑翔机,他操纵这些滑翔机从屋顶或山坡上一次又一次地跳下来。虽然总是一败涂地,但他却百折不回,从中积累了丰富的经验。",
      "然而探索总是要付出代价的。1896年 4月9日,李林塔尔操纵他的滑翔机从德国斯图伦附近的山坡上起飞后,恰遇一股强劲的风,他一下腾空很高,李林塔尔非常兴奋,然而他却全然不知滑翔机已达失速的边缘。正当他试图尝试一种新的控制方法时,滑翔机突然失速,一头栽向地面,滑翔机摔毁了,李林塔尔也受了致命的重伤——脊椎断裂,在送往医院的途中死亡。他在弥留之际,对弟弟古斯塔夫说:“总是要有人牺牲的......”",
      "德国人为了纪念他的功绩,为李林塔尔树立了一座纪念碑,上面写着“最伟大的老师” 。"
    ],
